public class Subscription
{
    private readonly IBookRepository _repository;
    private readonly ILogger<Subscription> _logger;

    public Subscription(IBookRepository repository, ILogger<Subscription> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    [Subscription]
    public IAsyncEnumerable<Book> BookAdded(
        [EventMessage] IAsyncEnumerable<Book> stream)
    {
        return stream;
    }
}

public class Mutation
{
    private readonly ITopicEventSender _sender;

    public Mutation(ITopicEventSender sender)
    {
        _sender = sender;
    }

    [Mutation]
    public async Task<Book> AddBookAsync(CreateBookInput input)
    {
        var book = new Book { /* ... */ };
        await _repository.AddAsync(book);

        await _sender.SendAsync(nameof(Subscription.BookAdded), book);
        return book;
    }
}
